//! OUTPUT.form returns its native form owner without author-property authority.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=owner><label id=label for=output>Result</label><output id=output for=seed>ready</output><input id=field value=seed></form><form id=other></form><output id=external form=other></output><div id=mount></div></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://output-form.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn output_form_canonical_readonly_descriptor_native_owner_and_genuine_brand(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),owner=document.getElementById('owner'),other=document.getElementById('other'),descriptor=Object.getOwnPropertyDescriptor(HTMLOutputElement.prototype,'form');if(!descriptor||typeof descriptor.get!=='function'||descriptor.set!==undefined||!descriptor.enumerable||!descriptor.configurable||descriptor.get.name!=='get form'||descriptor.get.length!==0||Object.hasOwn(output,'form'))throw 'canonical output form descriptor';if(output.form!==owner||descriptor.get.call(output)!==owner||document.getElementById('external').form!==other||document.getElementById('label').form!==owner)throw 'actual output owner';output.htmlFor='other';if(output.form!==owner)throw 'for tokens do not select own form';output.form=other;if(output.form!==owner||Object.hasOwn(output,'form'))throw 'readonly output form';var caught=false;try{(function(){'use strict';output.form=other;})();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'strict readonly';for(var bad of [{},Object.create(HTMLOutputElement.prototype),document.getElementById('label'),document.createElement('div'),document.createElementNS('urn:foreign','output')]){caught=false;try{descriptor.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'genuine output form brand';}"#);}
#[test]
fn output_form_inert_connected_exact_ids_first_blocker_and_detached_ancestor(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=document.implementation.createHTMLDocument('source'),outer=doc.createElement('form'),other=doc.createElement('form'),output=doc.createElement('output'),block=doc.createElement('div');outer.id='outer';other.id='A\ud800z';block.id='A�z';outer.appendChild(output);doc.body.appendChild(outer);doc.body.appendChild(block);doc.body.appendChild(other);output.setAttribute('form','A\ud800z');if(output.form!==other)throw 'exact connected explicit owner';block.id='A\ud800z';if(output.form!==null)throw 'first nonform ID blocker';doc.body.removeChild(block);if(output.form!==other)throw 'blocker removal';output.setAttribute('form','missing');if(output.form!==null)throw 'explicit miss';output.removeAttribute('form');if(output.form!==outer)throw 'ancestor owner';output.setAttribute('form','A\ud800z');doc.body.removeChild(outer);if(output.form!==outer)throw 'detached explicit ignored';outer.removeChild(output);if(output.form!==null)throw 'detached without form';"#);}
#[test]
fn output_form_author_shadows_and_overrides_preserve_saved_native_owner(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),owner=document.getElementById('owner'),descriptor=Object.getOwnPropertyDescriptor(HTMLOutputElement.prototype,'form'),calls=0;Object.defineProperty(output,'htmlFor',{get:function(){calls++;return 'other';},configurable:true});Object.defineProperty(output,'parentNode',{get:function(){calls++;return null;},configurable:true});Object.defineProperty(output,'id',{get:function(){calls++;return 'other';},configurable:true});if(output.form!==owner||calls)throw 'association ignores author getters';Object.defineProperty(output,'form',{value:'own',writable:true,configurable:true});output.form='changed';if(output.form!=='changed'||descriptor.get.call(output)!==owner)throw 'ordinary own shadow';delete output.form;Object.defineProperty(HTMLOutputElement.prototype,'form',{get:function(){return 'prototype';},configurable:true});if(output.form!=='prototype'||descriptor.get.call(output)!==owner)throw 'ordinary prototype override';delete HTMLOutputElement.prototype.form;if(output.form!==undefined||descriptor.get.call(output)!==owner)throw 'canonical deletion';Object.defineProperty(HTMLOutputElement.prototype,'form',descriptor);var count=0;for(var key in output)if(key==='form')count++;if(count!==1||Object.hasOwn(output,'form')||output.form!==owner||calls)throw 'restored inherited form';"#);}

#[test]
fn output_form_native_reflect_set_retains_its_existing_atomic_refusal(){let(mut d,mut f,mut p)=fixture();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let e=p.runtime.execute("Reflect.set(document.getElementById('output'),'form',null);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("Reflect.set on a native target is not implemented"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.begin_job();run(&mut d,&mut f,&mut p,"if(document.getElementById('output').form!==document.getElementById('owner'))throw 'native readonly recovery';");}
#[test]
fn output_form_inert_clone_adoption_and_xml_owner_need_no_main_slots(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=document.implementation.createHTMLDocument('source'),form=doc.createElement('form'),output=doc.createElement('output');form.appendChild(output);output.htmlFor='A\ud800z';var copy=form.cloneNode(true),target=document.implementation.createHTMLDocument('target');target.adoptNode(form);if(output.form!==form||copy.firstChild.form!==copy||copy.firstChild===output||output.ownerDocument!==target||copy.firstChild.htmlFor.value!=='A\ud800z')throw 'actual clone and adopted owner';"#);let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());p.begin_job();assert!(p.runtime.execute("document.importNode(output,true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err().contains("Import supports ordinary HTML containers"));assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);let slots=d.nodes.len();p.state.node_limit=slots;p.begin_job();run(&mut d,&mut f,&mut p,r#"var xml=new Document(),xform=xml.createElementNS('http://www.w3.org/1999/xhtml','form'),xoutput=xml.createElementNS('http://www.w3.org/1999/xhtml','output');xform.appendChild(xoutput);xoutput.setAttribute('form','missing');if(xoutput.form!==xform)throw 'detached HTML namespace output in XML owner';xml.appendChild(xform);if(xoutput.form!==null)throw 'connected explicit miss';xoutput.removeAttribute('form');if(xoutput.form!==xform||output.form!==form||copy.firstChild.form!==copy)throw 'fresh XML ancestor recovery';"#);assert_eq!(d.nodes.len(),slots);}
#[test]
fn output_form_actual_namespace_attributes_observer_and_foreign_blocker(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=document.implementation.createHTMLDocument('source'),outer=doc.createElement('form'),other=doc.createElement('form'),output=doc.createElement('output');other.id='A\ud800z';outer.appendChild(output);doc.body.appendChild(outer);doc.body.appendChild(other);output.setAttributeNS('urn:attribute','form','foreign');output.setAttributeNS(null,'form','A\ud800z');var actual=output.getAttributeNodeNS(null,'form'),foreign=output.getAttributeNodeNS('urn:attribute','form'),watch=new MutationObserver(function(){});watch.observe(output,{attributes:true,attributeOldValue:true});if(output.form!==other||watch.takeRecords().length||foreign.value!=='foreign')throw 'getter reads only actual null namespace';actual.value='missing';if(output.form!==null)throw 'attached actual Attr miss';output.removeAttributeNS(null,'form');if(output.form!==outer||foreign.ownerElement!==output)throw 'ancestor recovery with foreign collision';var records=watch.takeRecords();if(records.length!==2||records[0].oldValue!=='A\ud800z'||records[1].oldValue!=='missing')throw 'only actual writes observed';var foreignForm=doc.createElementNS('urn:element','form');foreignForm.setAttribute('id','A\ud800z');doc.body.insertBefore(foreignForm,other);output.setAttributeNS(null,'form','A\ud800z');if(output.form!==null)throw 'foreign first ID blocks HTML form';foreignForm.remove();if(output.form!==other)throw 'foreign blocker removal';"#);}
#[test]
fn output_form_resources_cancel_and_saved_child_origin_preserve_owner_and_recover(){for inert in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var doc=document.implementation.createHTMLDocument('source'),source=doc.createElement('output'),form=doc.createElement('form');form.id='target';source.setAttribute('form','target');doc.body.appendChild(form);doc.body.appendChild(source);"}else{"var source=document.getElementById('external'),form=document.getElementById('other');"});let Value::Host(source)=p.runtime.execute("source;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!()};p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;for mode in 0..4{p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let e=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.output_form_get(source).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.retained_limit=limit;p.state.execution_deadline=None;}p.begin_job();run(&mut d,&mut f,&mut p,r#"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var descriptor=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLOutputElement.prototype,'form');if(descriptor.get.call(source)!==form)throw 'saved child owner getter';"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.set_location(&crate::navigation::address("https://foreign-output-form.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();let e=p.runtime.execute("descriptor.get.call(source);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.set_location(&crate::navigation::address("https://output-form.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(descriptor.get.call(source)!==form)throw 'fresh native owner recovery';");}}
